import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Link } from 'react-router-dom';
import './App.css';
import VideoFeed from './VideoFeed';
import HeroSection from './components/HeroSection';

// Types for security events
interface SecurityEvent {
  id: string;
  timestamp: Date;
  type: string;
  description: string;
  location: string;
  severity: 'low' | 'medium' | 'high';
}

// Types for security statistics
interface SecurityStats {
  peopleCount: number;
  bottleCount: number;
  weaponCount: number;
  alertsTriggered: number;
}

function App() {
  // State for security events
  const [events, setEvents] = useState<SecurityEvent[]>([]);
  
  // State for security statistics
  const [stats, setStats] = useState<SecurityStats>({
    peopleCount: 0,
    bottleCount: 0,
    weaponCount: 0,
    alertsTriggered: 0
  });

  // Add event handler
  const addEvent = (event: SecurityEvent) => {
    setEvents(prevEvents => [event, ...prevEvents].slice(0, 100)); // Keep only last 100 events
    
    // Update stats based on event
    if (event.type === 'person_detected') {
      setStats(prev => ({ ...prev, peopleCount: prev.peopleCount + 1 }));
    } else if (event.type === 'bottle_detected') {
      setStats(prev => ({ ...prev, bottleCount: prev.bottleCount + 1 }));
    } else if (event.type === 'weapon_detected') {
      setStats(prev => ({ 
        ...prev, 
        weaponCount: prev.weaponCount + 1,
        alertsTriggered: prev.alertsTriggered + 1
      }));
    }
  };

  return (
    <Router>
      <div className="App">
        <Routes>
          <Route path="/" element={<HeroSection />} />
          <Route path="/dashboard" element={<Dashboard stats={stats} events={events} addEvent={addEvent} />} />
          <Route path="/settings" element={<Settings />} />
        </Routes>
      </div>
    </Router>
  );
}

// Dashboard Component
function Dashboard({ stats, events, addEvent }: { 
  stats: SecurityStats, 
  events: SecurityEvent[],
  addEvent: (event: SecurityEvent) => void
}) {
  return (
    <div className="dashboard">
      <header className="app-header">
        <div className="header-left">
          <h1><i className="fas fa-shield-alt"></i> Bar Security Tracker</h1>
        </div>
        <div className="header-right">
          <Link to="/" className="btn btn-sm btn-outline-light">
            <i className="fas fa-home"></i> Home
          </Link>
          <Link to="/settings" className="btn btn-sm btn-outline-light ms-2">
            <i className="fas fa-cog"></i> Settings
          </Link>
        </div>
      </header>

      <div className="security-stats">
        <div className="stat-card">
          <div className="stat-icon"><i className="fas fa-user"></i></div>
          <div className="stat-data">
            <h3>{stats.peopleCount}</h3>
            <p>People Detected</p>
          </div>
        </div>
        <div className="stat-card">
          <div className="stat-icon"><i className="fas fa-wine-bottle"></i></div>
          <div className="stat-data">
            <h3>{stats.bottleCount}</h3>
            <p>Bottles Detected</p>
          </div>
        </div>
        <div className="stat-card">
          <div className="stat-icon"><i className="fas fa-exclamation-triangle"></i></div>
          <div className="stat-data">
            <h3>{stats.weaponCount}</h3>
            <p>Weapons Detected</p>
          </div>
        </div>
        <div className="stat-card">
          <div className="stat-icon"><i className="fas fa-bell"></i></div>
          <div className="stat-data">
            <h3>{stats.alertsTriggered}</h3>
            <p>Alerts Triggered</p>
          </div>
        </div>
      </div>

      <div className="video-feeds-section">
        <h2><i className="fas fa-video"></i> Bartender Monitoring</h2>
        <div className="video-feeds-container">
          <VideoFeed 
            title="Main Bar - Bartender 1" 
            isMainFeed={true}
            onEvent={(event) => addEvent({
              ...event,
              location: "Main Bar"
            })}
          />
          <VideoFeed 
            title="Side Bar - Bartender 2" 
            isMainFeed={false}
            onEvent={(event) => addEvent({
              ...event,
              location: "Side Bar"
            })}
          />
        </div>
      </div>

      <div className="activity-log">
        <h2><i className="fas fa-clipboard-list"></i> Security Activity Log</h2>
        <div className="log-entries">
          {events.length === 0 ? (
            <div className="no-events">No security events recorded yet.</div>
          ) : (
            events.map(event => (
              <div key={event.id} className={`log-entry severity-${event.severity}`}>
                <div className="event-time">
                  {event.timestamp.toLocaleTimeString()}
                </div>
                <div className="event-icon">
                  {event.type === 'person_detected' && <i className="fas fa-user"></i>}
                  {event.type === 'bottle_detected' && <i className="fas fa-wine-bottle"></i>}
                  {event.type === 'weapon_detected' && <i className="fas fa-exclamation-triangle"></i>}
                </div>
                <div className="event-details">
                  <div className="event-title">{event.description}</div>
                  <div className="event-location">{event.location}</div>
                </div>
                <div className="event-severity">
                  {event.severity === 'high' && <span className="badge bg-danger">High</span>}
                  {event.severity === 'medium' && <span className="badge bg-warning">Medium</span>}
                  {event.severity === 'low' && <span className="badge bg-info">Low</span>}
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
}

