import React, { useState, useRef, useEffect } from 'react';
import './VideoFeed.css';

// Define a type for detection boxes
interface DetectionBox {
  id: string;
  x: number;
  y: number;
  width: number;
  height: number;
  type: 'person' | 'bottle' | 'weapon';
}

export interface VideoFeedProps {
  title: string;
  isMainFeed?: boolean;
  streamUrl?: string; // Make streamUrl optional
  onEvent?: (event: {
    id: string;
    timestamp: Date;
    type: string;
    description: string;
    severity: 'low' | 'medium' | 'high';
  }) => void;
}

const VideoFeed: React.FC<VideoFeedProps> = ({ 
  title, 
  isMainFeed = false,
  streamUrl,
  onEvent = () => {} // Default empty function if not provided
}) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const detectionOverlayRef = useRef<HTMLDivElement>(null);
  const [connectionStatus, setConnectionStatus] = useState<'connecting' | 'connected' | 'disconnected'>('connecting');
  const [connectionTime, setConnectionTime] = useState('00:00');
  const connectionStartTimeRef = useRef<Date | null>(null);
  const connectionTimerRef = useRef<number | null>(null);
  const [weaponDetectionEnabled, setWeaponDetectionEnabled] = useState(false);
  const [detections, setDetections] = useState<DetectionBox[]>([]);
  const detectionTimerRef = useRef<number | null>(null);

  // Initialize player
  const initializePlayer = () => {
    const videoElement = videoRef.current;
    if (!videoElement) return;

    // Demo mode: create a solid color background instead of using actual video
    // Set connection status as connected immediately
    setConnectionStatus('connected');
    connectionStartTimeRef.current = new Date();
    startStatsMonitoring();
    startMockDetections();

    // Clear any existing video source
    videoElement.removeAttribute('src');
    videoElement.load();
  };

  // Start stats monitoring
  const startStatsMonitoring = () => {
    if (connectionTimerRef.current) {
      clearInterval(connectionTimerRef.current);
    }
    
    connectionTimerRef.current = window.setInterval(() => {
      if (connectionStartTimeRef.current) {
        const now = new Date();
        const diffMs = now.getTime() - connectionStartTimeRef.current.getTime();
        const minutes = Math.floor(diffMs / 60000);
        const seconds = Math.floor((diffMs % 60000) / 1000);
        setConnectionTime(`${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`);
      }
    }, 1000);
  };

  // Stop stats monitoring
  const stopStatsMonitoring = () => {
    if (connectionTimerRef.current) {
      clearInterval(connectionTimerRef.current);
      connectionTimerRef.current = null;
    }
  };

  // Handle refresh button
  const handleRefresh = () => {
    // First disconnect
    setConnectionStatus('connecting');
    stopStatsMonitoring();
    if (detectionTimerRef.current) {
      clearInterval(detectionTimerRef.current);
      detectionTimerRef.current = null;
    }
    setDetections([]);
    
    // Then try to reconnect after a short delay
    setTimeout(() => {
      initializePlayer();
    }, 1000);
  };
  
  // Start mock detections
  const startMockDetections = () => {
    if (detectionTimerRef.current) {
      clearInterval(detectionTimerRef.current);
    }
    
    // Schedule random detections
    detectionTimerRef.current = window.setInterval(() => {
      const detectionType = ['person', 'bottle', 'weapon'][Math.floor(Math.random() * 3)] as 'person' | 'bottle' | 'weapon';
      addRandomDetection(detectionType);
    }, 3000 + Math.random() * 2000); // Random interval between 3-5 seconds
  };

  // Add random detection
  const addRandomDetection = (type: 'person' | 'bottle' | 'weapon') => {
    const detectionOverlay = detectionOverlayRef.current;
    if (!detectionOverlay) return;
    
    // Skip weapon detections if weapon detection is disabled
    if (type === 'weapon' && !weaponDetectionEnabled) return;

    const boxWidth = Math.floor(Math.random() * 150) + 50;
    const boxHeight = Math.floor(Math.random() * 150) + 50;
    const maxX = detectionOverlay.clientWidth - boxWidth;
    const maxY = detectionOverlay.clientHeight - boxHeight;
    const x = Math.floor(Math.random() * maxX);
    const y = Math.floor(Math.random() * maxY);

    const newDetection: DetectionBox = {
      id: `${type}-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`,
      x,
      y,
      width: boxWidth,
      height: boxHeight,
      type
    };

    // Create the event object to send back to parent
    const eventSeverity: 'low' | 'medium' | 'high' = 
      type === 'weapon' ? 'high' : 
      type === 'bottle' ? 'medium' : 'low';
      
    const event = {
      id: newDetection.id,
      timestamp: new Date(),
      type: `${type}_detected`,
      description: `${type.charAt(0).toUpperCase() + type.slice(1)} detected in ${title}`,
      severity: eventSeverity
    };

    // Call the onEvent callback
    onEvent(event);

    setDetections(prev => [...prev, newDetection]);

    // Remove detection after a few seconds
    setTimeout(() => {
      setDetections(prev => prev.filter(d => d.id !== newDetection.id));
    }, 5000);
  };

  // Toggle weapon detection
  const toggleWeaponDetection = () => {
    setWeaponDetectionEnabled(prev => !prev);
  };

  // Initialize and cleanup
  useEffect(() => {
    initializePlayer();
    
    return () => {
      stopStatsMonitoring();
      if (detectionTimerRef.current) {
        clearInterval(detectionTimerRef.current);
      }
    };
  }, []);

  return (
    <div className={`video-feed-container ${isMainFeed ? 'main-feed' : ''}`}>
      <div className="video-header">
        <div className="d-flex justify-content-between align-items-center">
          <h5 className="mb-0">
            <span className="live-indicator"></span>
            {title}
          </h5>
        </div>
      </div>
      <div className="video-wrapper">
        <video ref={videoRef} muted></video>
        
        {/* Demo placeholder */}
        <div className="demo-placeholder">
          <i className="fas fa-video camera-icon"></i>
          <div className="bartender-silhouette"></div>
          <p>Demo Mode: {title}</p>
        </div>
        
        <div ref={detectionOverlayRef} className="detection-overlay">
          {detections.map(detection => (
            <div
              key={detection.id}
              className={`detection-box ${detection.type}`}
              style={{
                width: `${detection.width}px`,
                height: `${detection.height}px`,
                left: `${detection.x}px`,
                top: `${detection.y}px`
              }}
            >
              <div className="label">
                {detection.type.charAt(0).toUpperCase() + detection.type.slice(1)}
              </div>
            </div>
          ))}
        </div>
      </div>
      <div className="video-controls">
        <div className="d-flex justify-content-between align-items-center">
          <div>
            <span className={`connection-status ${connectionStatus === 'connected' ? 'connected' : connectionStatus === 'disconnected' ? 'disconnected' : ''}`}>
              {connectionStatus === 'connected' ? 'Connected' : connectionStatus === 'disconnected' ? 'Disconnected' : 'Connecting...'}
            </span>
            <span className="connection-time ms-2">{connectionTime}</span>
          </div>
          <div>
            <button
              className={`btn ${weaponDetectionEnabled ? 'btn-danger' : 'btn-outline-danger'} btn-sm`}
              onClick={toggleWeaponDetection}
            >
              <i className="fas fa-exclamation-triangle me-1"></i> Weapon Detection
            </button>
            <button className="btn btn-primary btn-sm ms-2" onClick={handleRefresh}>
              <i className="fas fa-sync-alt"></i> Refresh
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default VideoFeed;
