import React from 'react';
import './ProgressiveBlur.css';

interface ProgressiveBlurProps {
  className?: string;
  direction: 'left' | 'right';
  blurIntensity?: number;
}

export const ProgressiveBlur: React.FC<ProgressiveBlurProps> = ({
  className = '',
  direction,
  blurIntensity = 1,
}) => {
  const blurClass = `blur-gradient-${direction}`;

  return (
    <div 
      className={`progressive-blur ${blurClass} ${className}`}
      style={{ '--blur-intensity': blurIntensity } as React.CSSProperties}
    />
  );
};

export default ProgressiveBlur;
