import React, { useRef, useEffect } from 'react';
import './InfiniteSlider.css';

interface InfiniteSliderProps {
  children: React.ReactNode;
  speed?: number;
  speedOnHover?: number;
  gap?: number;
}

export const InfiniteSlider: React.FC<InfiniteSliderProps> = ({
  children,
  speed = 40,
  speedOnHover = 20,
  gap = 30
}) => {
  const sliderRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const duplicatedContentRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!sliderRef.current || !contentRef.current || !duplicatedContentRef.current) return;

    // Clone the content
    duplicatedContentRef.current.innerHTML = contentRef.current.innerHTML;

    const slider = sliderRef.current;
    let isHovering = false;

    // Animation function
    let animationId: number;
    let lastTime = 0;
    let position = 0;
    const fps = 60;
    const interval = 1000 / fps;

    const animate = (currentTime: number) => {
      if (!contentRef.current) return;
      
      animationId = requestAnimationFrame(animate);
      
      const delta = currentTime - lastTime;
      
      if (delta >= interval) {
        const contentWidth = contentRef.current.offsetWidth;
        
        // Move the slider
        const moveSpeed = isHovering ? speedOnHover : speed;
        position -= moveSpeed / fps;
        
        // Reset position when content is fully scrolled
        if (Math.abs(position) >= contentWidth) {
          position = 0;
        }
        
        if (sliderRef.current) {
          sliderRef.current.style.transform = `translateX(${position}px)`;
        }
        
        lastTime = currentTime - (delta % interval);
      }
    };

    // Start animation
    animationId = requestAnimationFrame(animate);

    // Handle hover
    const handleMouseEnter = () => {
      isHovering = true;
    };

    const handleMouseLeave = () => {
      isHovering = false;
    };

    slider.addEventListener('mouseenter', handleMouseEnter);
    slider.addEventListener('mouseleave', handleMouseLeave);

    // Clean up
    return () => {
      cancelAnimationFrame(animationId);
      slider.removeEventListener('mouseenter', handleMouseEnter);
      slider.removeEventListener('mouseleave', handleMouseLeave);
    };
  }, [speed, speedOnHover]);

  return (
    <div className="infinite-slider-container">
      <div
        ref={sliderRef}
        className="infinite-slider"
        style={{ gap: `${gap}px` }}
      >
        <div ref={contentRef} className="slider-content">
          {children}
        </div>
        <div ref={duplicatedContentRef} className="slider-content duplicated"></div>
      </div>
    </div>
  );
};

export default InfiniteSlider;
